<?php
$loc=$_GET['location']??'';$locations=$pdo->query('SELECT DISTINCT location FROM units WHERE location IS NOT NULL ORDER BY location')->fetchAll(PDO::FETCH_COLUMN);
$where=$loc?' WHERE u.location=? ':'';$sql="SELECT u.location,COUNT(*) total,SUM(u.operational_status='Ready for Use') ready,SUM(u.operational_status='Breakdown') breakdown,SUM(u.operational_status='Downtime') downtime,COALESCE(SUM((SELECT SUM(m.actual_cost) FROM maintenance_orders m WHERE m.unit_id=u.id)),0) cost FROM units u $where GROUP BY u.location ORDER BY u.location";$stmt=$pdo->prepare($sql);$stmt->execute($loc?[$loc]:[]);$rows=$stmt->fetchAll();
?>
<div class="page-actions"><div><h3>Dashboard per Lokasi Kerja</h3></div><form class="search-form"><input type="hidden" name="page" value="location-dashboard"><select name="location"><option value="">Semua Lokasi</option><?php foreach($locations as $l):?><option <?=$loc===$l?'selected':''?>><?=e($l)?></option><?php endforeach;?></select><button class="btn">Filter</button></form></div>
<section class="kpis"><?php foreach($rows as $r):?><div class="card kpi"><div class="icon blue">⌖</div><div><div class="label"><?=e($r['location'])?></div><div class="value"><?=$r['ready']?>/<?=$r['total']?></div><div class="muted">Ready · Breakdown <?=$r['breakdown']?> · Downtime <?=$r['downtime']?></div></div></div><?php endforeach;?></section>
<div class="card panel"><table><thead><tr><th>Lokasi</th><th>Total Unit</th><th>Ready</th><th>Breakdown</th><th>Downtime</th><th>Availability Saat Ini</th><th>Biaya Perbaikan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['location'])?></td><td><?=$r['total']?></td><td><?=$r['ready']?></td><td><?=$r['breakdown']?></td><td><?=$r['downtime']?></td><td><?=number_format($r['total']?$r['ready']/$r['total']*100:0,1)?>%</td><td><?=rupiah($r['cost'])?></td></tr><?php endforeach;?></tbody></table></div>
